//-----------------------------------------------------------
data class AssignCampaignToExperimentCommand(@TargetAggregateIdentifier  val experimentId: UUID, val assignment: Campaign )

//-----------------------------------------------------------
// Command for unassigning a Campaign to a Experiment
//-----------------------------------------------------------
data class UnAssignCampaignFromExperimentCommand(@TargetAggregateIdentifier  val experimentId: UUID )

// multiple association commands
//-----------------------------------------------------------
// Command for adding a ExperimentVariant to a Experiment
//-----------------------------------------------------------
data class AssignVariantsToExperimentCommand(@TargetAggregateIdentifier  val experimentId: UUID, val addTo: ExperimentVariant )
//-----------------------------------------------------------
// Command for removing a ExperimentVariant from a Experiment
//-----------------------------------------------------------
data class RemoveVariantsFromExperimentCommand(@TargetAggregateIdentifier  val experimentId: UUID, val removeFrom: ExperimentVariant )

//-----------------------------------------------------------
// Command for producing an instance of a ExperimentVariant
//-----------------------------------------------------------
data class CreateExperimentVariantCommand(
    @TargetAggregateIdentifier var experimentVariantId: UUID? = null,
    var name: String? = null,
         @AttributeOverrides(
      AttributeOverride( name = "value", column = Column(name = "allocation_value"))
    )
    var allocation: Percentage? = null
)
//-----------------------------------------------------------
// Command for modifying an instance of a ExperimentVariant
//-----------------------------------------------------------
data class UpdateExperimentVariantCommand(
    @TargetAggregateIdentifier var experimentVariantId: UUID? = null,
    var name: String? = null,
         @AttributeOverrides(
      AttributeOverride( name = "value", column = Column(name = "allocation_value"))
    )
    var allocation: Percentage? = null,
    var experiment: Experiment? = null,
    var creativeVariation: CreativeVariation? = null,
    var lineItem: LineItem? = null
)
//-----------------------------------------------------------
// Command for removing an instance of a ExperimentVariant
//-----------------------------------------------------------
data class DeleteExperimentVariantCommand(@TargetAggregateIdentifier  var experimentVariantId: UUID? = null)

// single association commands
//-----------------------------------------------------------
// Command for assigning a Experiment to a ExperimentVariant
//-----------------------------------------------------------
data class AssignExperimentToExperimentVariantCommand(@TargetAggregateIdentifier  val experimentVariantId: UUID, val assignment: Experiment )

//-----------------------------------------------------------
// Command for unassigning a Experiment to a ExperimentVariant
//-----------------------------------------------------------
data class UnAssignExperimentFromExperimentVariantCommand(@TargetAggregateIdentifier  val experimentVariantId: UUID )
//-----------------------------------------------------------
// Command for assigning a CreativeVariation to a ExperimentVariant
//-----------------------------------------------------------
data class AssignCreativeVariationToExperimentVariantCommand(@TargetAggregateIdentifier  val experimentVariantId: UUID, val assignment: CreativeVariation )

//-----------------------------------------------------------
// Command for unassigning a CreativeVariation to a ExperimentVariant
//-----------------------------------------------------------
data class UnAssignCreativeVariationFromExperimentVariantCommand(@TargetAggregateIdentifier  val experimentVariantId: UUID )
//-----------------------------------------------------------
// Command for assigning a LineItem to a ExperimentVariant
//-----------------------------------------------------------
data class AssignLineItemToExperimentVariantCommand(@TargetAggregateIdentifier  val experimentVariantId: UUID, val assignment: LineItem )

//-----------------------------------------------------------
// Command for unassigning a LineItem to a ExperimentVariant
//-----------------------------------------------------------
data class UnAssignLineItemFromExperimentVariantCommand(@TargetAggregateIdentifier  val experimentVariantId: UUID )

// multiple association commands

//-----------------------------------------------------------
// Command for producing an instance of a GeoRegion
//-----------------------------------------------------------
data class CreateGeoRegionCommand(
    @TargetAggregateIdentifier var geoRegionId: UUID? = null,
    var code: String? = null,
    var name: String? = null,
    @Enumerated(EnumType.STRING) var regionType: GeoRegionType? = null
)
//-----------------------------------------------------------
// Command for modifying an instance of a GeoRegion
//-----------------------------------------------------------
data class UpdateGeoRegionCommand(
    @TargetAggregateIdentifier var geoRegionId: UUID? = null,
    var code: String? = null,
    var name: String? = null,
    var parent: GeoRegion? = null,
    var children:  Set<GeoRegion>? = null,
    @Enumerated(EnumType.STRING) var regionType: GeoRegionType? = null
)
//-----------------------------------------------------------
// Command for removing an instance of a GeoRegion
//-----------------------------------------------------------
data class DeleteGeoRegionCommand(@TargetAggregateIdentifier  var geoRegionId: UUID? = null)

// single association commands
//-----------------------------------------------------------
// Command for assigning a GeoRegion to a GeoRegion
//-----------------------------------------------------------
data class AssignParentToGeoRegionCommand(@TargetAggregateIdentifier  val geoRegionId: UUID, val assignment: GeoRegion )

//-----------------------------------------------------------
// Command for unassigning a GeoRegion to a GeoRegion
//-----------------------------------------------------------
data class UnAssignParentFromGeoRegionCommand(@TargetAggregateIdentifier  val geoRegionId: UUID )

// multiple association commands
//-----------------------------------------------------------
// Command for adding a GeoRegion to a GeoRegion
//-----------------------------------------------------------
data class AssignChildrenToGeoRegionCommand(@TargetAggregateIdentifier  val geoRegionId: UUID, val addTo: GeoRegion )
//-----------------------------------------------------------
// Command for removing a GeoRegion from a GeoRegion
//-----------------------------------------------------------
data class RemoveChildrenFromGeoRegionCommand(@TargetAggregateIdentifier  val geoRegionId: UUID, val removeFrom: GeoRegion )



